import Foundation
import NeuralCore

// The persistence boundary of the shell. The value types (HistoryEntry,
// Bookmark, TabState, Session, Suggestion) come straight from the Rust core
// (`NeuralCore`, generated by UniFFI), so there is no second model to keep in
// sync. `RustStore` is the production implementation; the protocol stays so
// tests could substitute a fake.

protocol BrowserStore: AnyObject {
    // History
    /// Queued on a background queue; errors are logged.
    func recordVisit(url: String, title: String, timestampMs: Int64)
    /// Queued on a background queue; errors are logged.
    func updateTitle(url: String, title: String)
    func recentHistory(limit: UInt32) throws -> [HistoryEntry]
    func searchHistory(query: String, limit: UInt32) throws -> [HistoryEntry]

    // Bookmarks
    @discardableResult
    func addBookmark(url: String, title: String, folderId: Int64?) throws -> Bookmark
    func removeBookmark(id: Int64) throws
    func listBookmarks(folderId: Int64?) throws -> [Bookmark]
    func isBookmarked(url: String) throws -> Bool

    // Session
    /// Queued on a background queue; errors are logged.
    func saveSession(tabs: [TabState], activeTabId: String?)
    func loadSession() throws -> Session

    // Settings
    func getSetting(key: String) throws -> String?
    func setSetting(key: String, value: String) throws

    // Suggestions and input
    /// Runs off the main thread and calls `completion` on the main queue.
    func suggest(query: String, limit: UInt32, completion: @escaping ([Suggestion]) -> Void)
    func resolveInput(text: String, searchTemplate: String) -> String

    /// Blocks until all queued writes are done. Called on quit and by tests.
    func flush()
}

enum SettingKey {
    static let searchTemplate = "search.template"
    static let sleepAfterMinutes = "tabs.sleepAfterMinutes"
    static func extensionGrant(_ id: String) -> String { "extensions.grant.\(id)" }
}

enum Defaults {
    static let searchTemplate = "https://duckduckgo.com/?q=%s"
    static let sleepAfterMinutes = 15.0
}

extension BrowserStore {
    var searchTemplate: String {
        ((try? getSetting(key: SettingKey.searchTemplate)) ?? nil) ?? Defaults.searchTemplate
    }
}

func nowMs() -> Int64 { Int64(Date().timeIntervalSince1970 * 1000) }
